import { lerp, clamp, ease } from "./helpers";

// ─── ix/iy = % of the actual india.png image (not the container) ──────────────
// Tweak these values if dots need nudging on your specific image
// ─── REPLACE just the MAP_DATA and update GAP in HotspotLayer ────────────────

