    { label: "Kerala",      pct: "8.42%", ix: 42, iy: 79, anchor: "left"   },
  ],
  truck: [
    { label: "Uttar Pradesh", pct: "2.73%", ix: 55, iy: 33, anchor: "left"   },
    { label: "Haryana",       pct: "5.01%", ix: 53, iy: 19, anchor: "right"  },
    { label: "Telangana",     pct: "2.56%", ix: 50, iy: 62, anchor: "left"   },
    { label: "Karnataka",     pct: "3.71%", ix: 50, iy: 68, anchor: "right"  },
    { label: "Tamil Nadu",    pct: "3.80%", ix: 46, iy: 78, anchor: "bottom" },
  ],
